import './movement.js';
import {bmi,category,weightRange,energy} from './calculations.js';
const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',body:'<circle cx="12" cy="5" r="2"/><path d="M7 21v-6L5 11l2-2h10l2 2-2 4v6M9 13v8m6-8v8M8 9l4 5 4-5"/>',flame:'<path d="M13 2c1 6-4 6-2 10 2-1 3-3 3-5 4 3 6 6 5 10a7 7 0 0 1-14-1c0-4 2-6 4-8 0 3 1 3 2 4"/><path d="M12 15c-4 4 1 7 3 3"/>',book:'<path d="M12 5v16M3 4c4-1 6 0 9 2 3-2 5-3 9-2v15c-4-1-6 0-9 2-3-2-5-3-9-2Z"/><path d="m6 8 3 1m6 0 3-1M6 12l3 1m6 0 3-1"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',plate:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="4"/><path d="M1 4v6m2-6v6m-2 0h2v11M23 4v17"/>',walk:'<circle cx="14" cy="4" r="2"/><path d="m7 12 4-4 4 2 4 2m-7-3-2 7-5 5m5-5 6 1 2 5M9 8l-2 3"/>',moon:'<path d="M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z"/><path d="m17 3 .5 2L20 6l-2.5.5L17 9l-.5-2.5L14 6l2.5-1Z"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.book}</svg>`;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
function route(){const page=location.hash.slice(1)||'overview'; const current=['overview','bmi','calories','guides','movement'].includes(page)?page:'overview';document.querySelectorAll('.page').forEach(el=>el.hidden=el.id!==current);document.querySelectorAll('[data-nav]').forEach(el=>{const active=el.dataset.nav===current;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});document.title=({overview:'Dein gesunder Weg',bmi:'BMI & Idealgewicht',calories:'Kaloriendefizit-Rechner',guides:'Wissen & Guides',movement:'Bewegungsplan'})[current]+' · Calion';window.scrollTo(0,0);}
window.addEventListener('hashchange',()=>{route();document.querySelector('#main').focus({preventScroll:true});});route();
const number=(n,d=0)=>n.toLocaleString('de-DE',{minimumFractionDigits:d,maximumFractionDigits:d});
const val=id=>Number(document.getElementById(id).value);
const reveal=el=>{if(matchMedia('(max-width:600px)').matches)el.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});};
document.getElementById('bmi-form').addEventListener('submit',e=>{e.preventDefault();const height=val('bmi-height'),weight=val('bmi-weight'),age=val('bmi-age');const value=bmi(weight,height),range=weightRange(height);const target=document.getElementById('bmi-result');const advice=value<18.5?'Dein BMI liegt unter dem Standardbereich. Ein Kaloriendefizit ist hier nicht geeignet. Lass dein Gewicht und mögliche Ursachen ärztlich einordnen.':value<25?'Dein BMI liegt im Standardbereich. Aus diesem Wert allein ergibt sich kein Anlass abzunehmen. Bewegung und ausgewogenes Essen unterstützen dein Wohlbefinden.':'Dein BMI liegt über dem Standardbereich. Er ist ein erster Hinweis, aber keine Diagnose. Eine ärztliche Einordnung kann helfen, ein sinnvolles persönliches Ziel zu finden.';target.innerHTML=`<span class="result-label">DEIN BODY-MASS-INDEX</span><div class="result-value">${number(value,1)}</div><span class="result-badge">${category(value)}</span><div class="bmi-scale"><span class="bmi-pointer" style="left:${Math.min(99,Math.max(1,(value-12)/28*100))}%"></span></div><div class="scale-labels"><span>12</span><span>18,5</span><span>25</span><span>30</span><span>40+</span></div><h3>Gewichtsbereich zur Orientierung</h3><div class="range-value">${number(range[0],1)}–${number(range[1],1)} <small>kg</small></div><p>Bei ${number(height,1)} cm Körpergröße, entsprechend BMI 18,5–24,9. Kein individuell vorgeschriebenes Zielgewicht.</p><div class="result-hint">${advice}${age>=65?' Ab 65 Jahren ist der Standardbereich besonders vorsichtig zu interpretieren; Muskelmasse und Ernährungszustand sind wichtiger als eine starre Grenze.':''}</div>`;reveal(target);});
document.getElementById('calorie-form').addEventListener('submit',e=>{e.preventDefault();const data={weight:val('cal-weight'),height:val('cal-height'),age:val('cal-age'),sex:document.getElementById('cal-sex').value,activity:val('activity'),deficit:val('deficit')};const result=energy(data),target=document.getElementById('cal-result');const format=values=>values.map(x=>number(Math.round(x/10)*10)).join('–');if(result.underweight){target.innerHTML='<span class="result-symbol">♡</span><h2>Dein Körper braucht Unterstützung.</h2><p>Dein BMI liegt unter 18,5. Deshalb zeigen wir hier kein Kaloriendefizit und kein Abnehmziel. Eine ärztliche Praxis oder qualifizierte Ernährungsberatung kann dich individuell begleiten.</p><a class="button" href="#bmi" style="margin-top:25px">BMI einordnen lassen <span><svg class="arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg></span></a>';reveal(target);return;}target.innerHTML=`<span class="result-label">DEINE GESCHÄTZTE ENERGIEBILANZ</span><h2 style="margin-top:15px">Verstehe deinen Bedarf.</h2><div class="energy-row"><span>Ruheenergiebedarf</span><b>${format(result.resting)} kcal</b></div><div class="energy-row"><span>Gesamtbedarf pro Tag</span><b>${format(result.total)} kcal</b></div>${result.needsAdvice?'<div class="energy-target"><h3 style="margin-top:0">Individuelle Beratung sinnvoll</h3><p>Das gewählte Defizit würde zu einem zu niedrigen Schätzwert führen. Wir geben deshalb kein Kalorienziel aus. Wähle ein sanfteres Defizit oder lass deinen Bedarf fachlich bestimmen.</p></div>':`<div class="energy-row"><span>Defizit (${number(data.deficit*100)} %)</span><b>−${format(result.reduction)} kcal</b></div><div class="energy-target"><span class="result-label">RECHNERISCHE ORIENTIERUNG / TAG</span><strong>${format(result.target)} <small>kcal</small></strong><small>Ein Schätzwert, kein verbindliches Tageslimit.</small></div>`}<p>Der Gesamtbedarf umfasst Ruheenergie und geschätzte Alltagsaktivität. Zusätzliche Sportkalorien nicht noch einmal aufschlagen.</p><div class="result-hint">${bmi(data.weight,data.height)<25?'Dein BMI liegt im Normalbereich. Eine Gewichtsabnahme ist daraus nicht automatisch nötig. ':''}${data.age>=65?'Ab 65 Jahren bitte insbesondere Muskelerhalt und ausreichende Ernährung fachlich besprechen. ':''}Beobachte dein Wohlbefinden und passe nach einigen Wochen mit fachlicher Unterstützung an. Bei Erschöpfung, starkem Hunger oder Schwindel das Defizit nicht weiter erhöhen.</div>`;reveal(target);});
const guides=[
{title:'Gesund abnehmen: Was wirklich zählt',category:'Grundlagen',time:5,icon:'plate',summary:'Die wichtigsten Grundlagen für einen entspannten Start.',body:`<p>Abnehmen gelingt langfristig eher mit Gewohnheiten, die du beibehalten kannst. Eine schnelle Veränderung auf der Waage ist oft auch Wasser – kein Beweis für nachhaltigen Fettverlust.</p><h3>1. Verstehe die Energiebilanz</h3><p>Wenn dein Körper über längere Zeit weniger Energie erhält, als er verbraucht, baut er Energiereserven ab. Ein moderates Defizit ist meist besser durchzuhalten als eine strenge Diät. Der Rechner gibt dir dafür eine grobe Orientierung.</p><h3>2. Starte mit einer Veränderung</h3><p>Wähle für die nächste Woche eine konkrete Sache: zum Mittagessen Gemüse ergänzen, Wasser statt Softdrinks trinken oder nach dem Essen zehn Minuten spazieren gehen. Es muss in deinen Alltag passen.</p><h3>3. Denke in Wochen, nicht in Tagen</h3><p>Salz, Verdauung, Zyklus und Training verändern dein Gewicht kurzfristig. Wenn du dich wiegen möchtest, vergleiche ähnliche Bedingungen über mehrere Wochen. Energie, Kraft und Schlaf zählen ebenfalls.</p>`,takeaway:'Wähle heute eine kleine Gewohnheit, die du auch an einem stressigen Tag umsetzen kannst.'},
{title:'Kaloriendefizit einfach erklärt',category:'Grundlagen',time:4,icon:'flame',summary:'Warum weniger nicht immer besser ist.',body:`<p>Ein Defizit ist die Differenz zwischen deinem Energieverbrauch und deiner Energiezufuhr. Es ist keine Aufforderung, möglichst wenig zu essen.</p><h3>Ein verständliches Beispiel</h3><p>Bei einem geschätzten Gesamtbedarf von 2.200 kcal ergibt ein Defizit von 15 % rechnerisch 330 kcal. Übrig bleiben rund 1.870 kcal. Das ist ein Rechenbeispiel und keine Empfehlung für jede Person.</p><h3>Warum ein kleines Defizit helfen kann</h3><p>Ein Einstieg mit etwa 10–15 % kann den Alltag leichter machen als eine starke Einschränkung. Regelmäßige Mahlzeiten, sättigende Lebensmittel und Bewegung helfen, ohne jeden Bissen zu zählen.</p><h3>Wann du gegensteuern solltest</h3><p>Ständiger Hunger, Müdigkeit, Schwindel oder eine ausbleibende Periode sind keine Erfolgszeichen. Verzichte auf weiteres Einschränken und suche medizinischen Rat. Ein Bedarf aus einer Formel kann deutlich vom tatsächlichen Verbrauch abweichen.</p>`,takeaway:'Dein Defizit sollte deinen Alltag unterstützen – nicht deine Energie für ihn aufbrauchen.'},
{title:'Mehr Bewegung, die zu dir passt',category:'Alltag',time:4,icon:'walk',summary:'Kleine Schritte machen im Alltag einen Unterschied.',body:`<p>Du brauchst weder ein Fitnessstudio noch einen perfekten Trainingsplan, um aktiver zu werden. Beginne dort, wo du gerade stehst.</p><h3>Alltagsbewegung zählt</h3><p>Gehe kurze Wege zu Fuß, steige eine Station früher aus oder mache aktive Pausen am Schreibtisch. Erhöhe die Bewegung langsam. 10.000 Schritte sind keine magische Pflichtzahl.</p><h3>Ausdauer und Kraft ergänzen sich</h3><p>Die WHO empfiehlt Erwachsenen pro Woche 150–300 Minuten moderate Bewegung oder 75–150 Minuten intensive Bewegung sowie Krafttraining an mindestens zwei Tagen. Das ist eine Orientierung, kein Einstiegstest. Auch weniger ist besser als gar keine Bewegung.</p><h3>Finde etwas, das dir gefällt</h3><p>Tanzen, Radfahren, Schwimmen oder ein Spaziergang mit Freunden: Freude macht Wiederholung wahrscheinlicher. Bei Schmerzen, Vorerkrankungen oder nach längerer Pause kläre passende Belastungen ab.</p>`,takeaway:'Plane einen zehnminütigen Spaziergang ein. Ein kleiner Anfang darf klein bleiben.'},
{title:'Satt essen statt ständig verzichten',category:'Ernährung',time:5,icon:'plate',summary:'Baue Mahlzeiten, die sättigen und dir schmecken.',body:`<p>Sättigende Mahlzeiten machen es leichter, auf den eigenen Hunger zu hören. Verbote und Schuldgefühle helfen dabei selten.</p><h3>Der Teller als einfache Orientierung</h3><p>Fülle etwa die Hälfte mit Gemüse oder Salat, ein Viertel mit einer Eiweißquelle und ein Viertel mit Kartoffeln oder Vollkornprodukten. Ergänze etwas pflanzliches Öl oder Nüsse. Die Aufteilung ist flexibel, keine starre Regel.</p><h3>Eiweiß und Ballaststoffe</h3><p>Hülsenfrüchte, Tofu, Eier, Milchprodukte, Fisch oder andere passende Eiweißquellen können Teil deiner Mahlzeiten sein. Gemüse, Obst und Vollkorn liefern Ballaststoffe. Steigere Ballaststoffe langsam und trinke ausreichend.</p><h3>Genuss gehört dazu</h3><p>Auch dein Lieblingsdessert darf Platz haben. Iss möglichst aufmerksam und höre auf Hunger und Sättigung. Es gibt keine Lebensmittel, die allein über Erfolg oder Misserfolg entscheiden.</p>`,takeaway:'Ergänze zuerst etwas Sättigendes, bevor du über das Weglassen nachdenkst.'},
{title:'Schlaf, Stress und dein Wohlbefinden',category:'Alltag',time:3,icon:'moon',summary:'Warum Erholung zu gesunden Gewohnheiten gehört.',body:`<p>Zu wenig Schlaf und dauerhafter Stress können Hunger, Appetit und Energie beeinflussen. Sie sind ein Teil des Gesamtbilds – kein persönliches Versagen.</p><h3>Gib Erholung einen festen Platz</h3><p>Für viele Erwachsene sind etwa sieben bis neun Stunden Schlaf ein guter Rahmen. Regelmäßige Schlafenszeiten, ein dunkles Zimmer und ein ruhiger Tagesausklang können helfen. Dein individueller Bedarf kann abweichen.</p><h3>Mach den Alltag leichter</h3><p>Plane einfache Mahlzeiten, halte praktische Vorräte bereit und gönne dir Pausen. Bei emotionalem Essen hilft es manchmal zu fragen: Habe ich Hunger, brauche ich Ruhe oder gerade Unterstützung? Essen darf trotzdem auch Freude machen.</p><h3>Hol dir Unterstützung</h3><p>Anhaltende Schlafprobleme, Erschöpfung oder belastende Essmuster verdienen professionelle Hilfe. Noch strengere Regeln sind dafür keine Lösung.</p>`,takeaway:'Plane heute nicht nur Aufgaben, sondern auch eine kleine Pause ein.'},
{title:'BMI verstehen – mit seinen Grenzen',category:'Grundlagen',time:4,icon:'body',summary:'Was die Zahl verrät und was sie offenlässt.',body:`<p>Der Body-Mass-Index setzt Gewicht und Körpergröße ins Verhältnis: Gewicht in Kilogramm geteilt durch die Körpergröße in Metern zum Quadrat. Er ist ein grobes Maß, keine vollständige Gesundheitsbewertung.</p><h3>Die Standardbereiche für Erwachsene</h3><p>Unter 18,5 gilt als Untergewicht, 18,5 bis unter 25 als Normalgewicht, 25 bis unter 30 als Übergewicht und ab 30 als Adipositas. Die Bezeichnungen beschreiben statistische Kategorien und nicht deinen Wert oder deine Lebensweise.</p><h3>Was der BMI nicht misst</h3><p>Muskelmasse, Fettverteilung, Fitness und Blutwerte werden nicht erfasst. Menschen mit viel Muskelmasse können einen erhöhten BMI haben, ohne dass daraus automatisch ein Abnehmbedarf folgt.</p><h3>Persönliche Einordnung bleibt wichtig</h3><p>Für Kinder und Jugendliche gelten andere, alters- und geschlechtsspezifische Referenzen. In Schwangerschaft, Stillzeit und im höheren Alter sind zusätzliche Aspekte entscheidend. Ein persönliches Ziel besprichst du am besten mit einer qualifizierten Fachperson.</p>`,takeaway:'Nutze den BMI als einen Hinweis unter mehreren – nicht als Urteil über deinen Körper.'}
];
function card(g,i){return `<button class="article-card" data-guide="${i}"><div class="article-art art-${i%3}">${icon(g.icon)}</div><div class="article-body"><div class="article-meta"><span>${g.category}</span><span>${g.time} Min. Lesezeit</span></div><h3>${g.title}</h3><p>${g.summary}</p><span class="article-bottom">Guide lesen <span><svg class="arrow" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg></span></span></div></button>`;}
document.getElementById('home-guides').innerHTML=guides.slice(0,3).map(card).join('');
function renderGuides(filter='all'){document.getElementById('all-guides').innerHTML=guides.map((g,i)=>filter==='all'||g.category===filter?card(g,i):'').join('');}
renderGuides();document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});renderGuides(button.dataset.filter);}));
document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter==='all')));
const dialog=document.getElementById('article-dialog');
document.addEventListener('click',e=>{const button=e.target.closest('[data-guide]');if(!button)return;const g=guides[Number(button.dataset.guide)];document.getElementById('dialog-content').innerHTML=`<span class="eyebrow">${g.category.toUpperCase()} · ${g.time} MIN. LESEZEIT</span><h2 id="dialog-title">${g.title}</h2>${g.body}<div class="article-takeaway"><h3 style="margin:0">Dein kleiner nächster Schritt</h3><p>${g.takeaway}</p></div>`;dialog.setAttribute('aria-labelledby','dialog-title');dialog.showModal();dialog.scrollTop=0;});
document.getElementById('close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
document.getElementById('about-button').addEventListener('click',()=>{document.getElementById('dialog-content').innerHTML=`<span class="eyebrow">TRANSPARENT & MIT BEDACHT</span><h2 id="dialog-title">Hinweise & Quellen</h2><h3>Gesundheitsinformationen</h3><p>Calion vermittelt allgemeines Wissen für Erwachsene. Die Inhalte und Rechenergebnisse sind keine Diagnose und ersetzen keine ärztliche oder ernährungsmedizinische Beratung. Ein „Idealgewicht“ lässt sich nicht allein aus Alter, Geschlecht und Körpergröße bestimmen.</p><h3>So rechnen wir</h3><p>BMI = kg / m². Die Standardgrenzen für Erwachsene stammen aus der WHO-Einordnung. Der Gewichtsbereich entspricht BMI 18,5–24,9. Ruheenergiebedarf nach Mifflin-St Jeor: 10 × kg + 6,25 × cm − 5 × Alter + Konstante (−161 oder +5). Den Gesamtbedarf schätzen wir mit Aktivitätsfaktoren von 1,2 bis 1,725. Die Formelvarianten sind Näherungen und passen nicht auf jede individuelle Hormon- oder Körperkonstellation.</p><p>Der Rechner gibt keine Defizitziele unter dem geschätzten Ruhebedarf aus. Zusätzlich unterdrückt er Werte unter 1.200 kcal (weibliche Formel) bzw. 1.500 kcal (männliche Formel oder Spanne). Diese technischen Grenzen sind kein Beleg, dass höhere Werte individuell sicher oder ausreichend sind.</p><h3>Weiterlesen</h3><ul><li><a href="https://www.who.int/news-room/fact-sheets/detail/obesity-and-overweight" target="_blank" rel="noopener noreferrer">WHO: Obesity and overweight</a></li><li><a href="https://pubmed.ncbi.nlm.nih.gov/2305711/" target="_blank" rel="noopener noreferrer">Mifflin et al. (1990): Ruheenergiebedarf</a></li><li><a href="https://www.who.int/news-room/fact-sheets/detail/physical-activity" target="_blank" rel="noopener noreferrer">WHO: Bewegungsempfehlungen</a></li><li><a href="https://www.dge.de/gesunde-ernaehrung/gut-essen-und-trinken/dge-empfehlungen/" target="_blank" rel="noopener noreferrer">DGE: Gut essen und trinken</a></li></ul><h3>Deine Daten & externe Inhalte</h3><p>Die Rechner verarbeiten deine Eingaben ausschließlich im Arbeitsspeicher deines Browsers. Calion setzt keine Analyse- oder Tracking-Dienste ein und speichert keine Gesundheitswerte. Nur deine Auswahl für den hellen oder dunklen Modus wird lokal im Browser gespeichert. Beim Aufruf der Seite verarbeitet der Hosting-Anbieter technisch notwendige Verbindungsdaten. Schriften werden von Google Fonts geladen; dabei wird unter anderem deine IP-Adresse an Google übermittelt. Beim Öffnen externer Quellen gelten deren Datenschutzregeln.</p><h3>Bildnachweis</h3><p>Food-Fotografie: Unsplash. Illustrationen: Calion.</p>`;dialog.setAttribute('aria-labelledby','dialog-title');dialog.showModal();dialog.scrollTop=0;});
